// Miroir JS de lib/product-matching.ts (extractModel) - garder synchronise
// manuellement, ce workflow n8n ne peut pas importer le code TypeScript du repo.
const CATEGORY_PREFIXES = {
  raquettes: ['Raquette de tennis '],
  cordages: ['Cordage de tennis '],
  chaussures: ['Chaussures de tennis ', 'Chaussure de tennis '],
  accessoires: ['Balles de tennis Carton ', 'Balles de tennis ', 'Sac de tennis '],
};

// Pages categorie ProTennis retenues (D-2026-09-22-08) : exclusivement des pages
// tennis identifiees par leur slug, jamais une page toutes-categories du site
// (resout GAP-2026-09-22-09). balle-tennis/bagagerie-tennis n'ont pas de
// categorie dediee dans le modele -> rattachees a 'accessoires' (choix utilisateur).
const CATEGORY_PAGES = [
  { category: 'raquettes', url: 'https://www.protennis.fr/973-raquette-de-tennis' },
  { category: 'cordages', url: 'https://www.protennis.fr/977-cordage-raquette-tennis' },
  { category: 'chaussures', url: 'https://www.protennis.fr/974-chaussure-de-tennis' },
  { category: 'textile', url: 'https://www.protennis.fr/975-vetement-de-tennis' },
  { category: 'accessoires', url: 'https://www.protennis.fr/978-accessoire-tennis' },
  { category: 'accessoires', url: 'https://www.protennis.fr/979-balle-tennis' },
  { category: 'accessoires', url: 'https://www.protennis.fr/976-bagagerie-tennis' },
];

// Filet de securite : ProTennis est multi-sports, une fiche hors tennis peut se
// glisser sur une page tennis (deja observe : balles de squash sur une page
// raquettes). On l'ecarte au titre plutot que de se fier uniquement a l'URL.
// Pas de \b : des marques composees comme 'Bullpadel' n'ont pas de frontiere de
// mot avant 'padel' mais restent bien du materiel padel, pas tennis (verifie sur
// donnees reelles : 'Gel Deshydratant Bullpadel ...' sur la page accessoires).
const OTHER_SPORTS_PATTERN = /squash|padel|badminton|pickleball/i;

const REQUEST_HEADERS = {
  'User-Agent': 'deals-tennis-bot/1.0 (+https://deals-tennis.vercel.app)',
  // Indispensable : sans cet Accept, PrestaShop renvoie un fragment JSON au lieu
  // de la page HTML complete (bug decouvert lors du build initial, D-2026-09-22-03).
  Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
};

function parseEuro(str) {
  return parseFloat(str.replace(/\s|&nbsp;| /g, '').replace(',', '.'));
}

function stripTags(str) {
  return str.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function extractModel(title, brand, category) {
  let model = title;

  for (const prefix of CATEGORY_PREFIXES[category] || []) {
    if (model.toLowerCase().startsWith(prefix.toLowerCase())) {
      model = model.slice(prefix.length);
      break;
    }
  }

  const brandPattern = new RegExp(`\\b${escapeRegExp(brand)}\\b`, 'i');
  model = model.replace(brandPattern, '');

  model = model.replace(/\bnon\s+cord[ée]e?\b/gi, '');
  model = model.replace(/\bcord[ée]e?\b/gi, '');

  return model.replace(/\s+/g, ' ').trim();
}

function parseArticles(html, category) {
  const merchantId = '9bcb1729-926d-4462-b949-57f991e08673';
  // Chaque page categorie affiche aussi un bloc 'Nos recommandations pour : ...'
  // (section 'featured-products', module nkmsuggestedproducts) qui montre des
  // produits d'autres categories/pages identiques sur toutes les pages -> source
  // de doublons et de mauvais rattachement de categorie si on ne l'exclut pas
  // (verifie reellement : 6 des 42 articles de la page 1 raquettes venaient de ce
  // bloc, dont un sac de tennis). On ne garde que la vraie grille de resultats.
  const withoutFeatured = html.replace(/<section class="featured-products[\s\S]*?<\/section>/g, '');
  const articles = withoutFeatured.match(/<article class="product-miniature[\s\S]*?<\/article>/g) || [];
  const items = [];

  for (const block of articles) {
    const urlMatch = block.match(/<a href="([^"]+)"[^>]*class="thumbnail product-thumbnail">/);
    const imgMatch = block.match(/data-full-size-image-url="([^"]+)"/) || block.match(/<img\s+src="([^"]+)"/);
    const titleMatch = block.match(/<h3 class="h3 product-title">\s*<a[^>]*>\s*([\s\S]*?)\s*<\/a>/);
    const priceMatch = block.match(/<span class="price" aria-label="Prix">\s*([\d.,\s ]+)\s*€\s*<\/span>/);
    const regularMatch = block.match(/<span class="regular-price" aria-label="Prix de base">\s*([\d.,\s ]+)\s*€\s*<\/span>/);
    const brandMatch = block.match(/alt="([^"]+)"\s+class="brand-logo"/);

    if (!urlMatch || !titleMatch || !priceMatch || !regularMatch || !brandMatch || !imgMatch) continue;

    const title = stripTags(titleMatch[1]);
    if (OTHER_SPORTS_PATTERN.test(title)) continue;

    const originalPrice = parseEuro(regularMatch[1]);
    const discountedPrice = parseEuro(priceMatch[1]);
    if (!(originalPrice > discountedPrice) || !(discountedPrice > 0)) continue;

    const discountPercentage = Math.round(((originalPrice - discountedPrice) / originalPrice) * 100);
    const brand = brandMatch[1].trim();

    items.push({
      json: {
        title,
        brand,
        category,
        image_url: imgMatch[1],
        original_price: originalPrice,
        discounted_price: discountedPrice,
        discount_percentage: discountPercentage,
        merchant_id: merchantId,
        affiliate_url: urlMatch[1],
        model: extractModel(title, brand, category),
      },
    });
  }

  return items;
}

function maxPageFromHtml(html) {
  const matches = [...html.matchAll(/[?&]page=([0-9]+)/g)].map((m) => parseInt(m[1], 10));
  return matches.length > 0 ? Math.max(1, ...matches) : 1;
}

async function fetchHtml(url) {
  return this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: REQUEST_HEADERS,
  });
}

const allItems = [];

for (const page of CATEGORY_PAGES) {
  const firstPageHtml = await fetchHtml.call(this, page.url);
  allItems.push(...parseArticles(firstPageHtml, page.category));

  const pageCount = maxPageFromHtml(firstPageHtml);
  for (let n = 2; n <= pageCount; n++) {
    const html = await fetchHtml.call(this, `${page.url}?page=${n}`);
    allItems.push(...parseArticles(html, page.category));
  }
}

// ProTennis affiche un bloc de produits mis en avant identique en tete de chaque
// page paginee (verifie reellement : ~7 produits communs entre la page 1 et la
// page 5 de /973-raquette-de-tennis) -> memes URLs vues plusieurs fois. Dedup
// par affiliate_url pour eviter des upserts redondants (l'upsert est deja
// idempotent, ceci ne change aucun resultat, seulement le nombre de requetes).
const seenUrls = new Set();
const dedupedItems = [];
for (const item of allItems) {
  if (seenUrls.has(item.json.affiliate_url)) continue;
  seenUrls.add(item.json.affiliate_url);
  dedupedItems.push(item);
}

return dedupedItems;

const items = $input.all();
if (items.length === 0) {
  return [];
}
const affiliateUrls = items.map((i) => i.json.affiliate_url);
const merchantId = items[0].json.merchant_id;
return [{ json: { merchant_id: merchantId, affiliate_urls: affiliateUrls } }];
